There is an integer $N_0\ge2$ such that, for every $N\ge N_0$ and $Q=3(N-1)$, $$\label{eq:main}
 H_{N,Q}\ge\frac1{25}\bigl(I-P_{\mathrm L,N}\bigr)
 \qquad\text{on }\bigwedge^N U_Q,$$ where $P_{\mathrm L,N}$ projects onto the line spanned by $$\Psi_{\mathrm L,N}=\prod_{i<j}(u_iv_j-u_jv_i)^3.$$

On $\mathcal F_Q$, $$\label{eq:square}
 H^2=H+\mathcal L_3\!\left(W_3(W_3^\dagger W_3-I)W_3^\dagger\right)
       +\mathcal L_4(W_4W_4^\dagger).$$

The coefficient of $e_i\wedge e_j$ in $v_p$, for $i<j$, vanishes unless $i+j=p+1$, and otherwise equals $$\label{eq:pair}
 v_p(i,j)=(i-j)\sqrt{\frac{(Q)_i(Q)_j\,p!}{Q(2Q-2)_p\,i!j!}}.$$ For fixed $p,i,j$, its limit is $$\label{eq:pairstar}
 v_p^*(i,j)=(i-j)\sqrt{\frac{p!}{2^p i!j!}}\,\mathbf1_{i+j=p+1}.$$

$$\label{eq:q}
 W_3^\dagger W_3-I=\sum_{z=0}^Qq_z(Q)R_{3,z},\qquad
 q_z(Q)=(-1)^z\frac{(Q)_z}{(2Q-2)_z}
          \left(3z-1-\frac{z(z+1)}Q\right).$$ In particular $W_3R_{3,z}=0$ for $z=0,1,3$ whenever these indices are allowed. For fixed $z$, $$\label{eq:qlimit}
 q_z(Q)\longrightarrow (3z-1)(-1/2)^z.$$

Let $W$ be a linear map between finite-dimensional Hilbert spaces, $G=W^\dagger W$, and let $C$ be self-adjoint on the domain of $W$. Then $$GCG\ge0\quad\Longleftrightarrow\quad WCW^\dagger\ge0.$$ On $\mathcal F_{\mathrm{loc}}$, for any fixed finite collection $A_b=c_kc_jB(v_p^*)$ with $0\le p\le23$ and $0\le j,k\le24$, $$\label{eq:annihilatorbound}
 \sum_b\lVert A_b\psi\rVert^2\le C_0\langle \psi,h_*\psi\rangle,
 \qquad h_*:=\sum_{p=0}^{23}B(v_p^*)^\dagger B(v_p^*),$$ where $C_0$ depends only on the collection.

For $Q\ge24$ and $1\le D\le23$, put $$C_D^Q=(d_D/d_a)\chi-E_D^Q+\varepsilon I,
 \qquad h_Q=\sum_{p=0}^{23}B_p^\dagger B_p.$$ Assuming <a href="#eq:4certificate" data-reference-type="eqref" data-reference="eq:4certificate">[eq:4certificate]</a>, there is a scalar $\rho_Q\ge0$, independent of $D$ and tending to zero as $Q\to\infty$, such that $$\label{eq:relative}
 \sum_{r,s\in\mathcal R_D}(C_D^Q)_{rs}
 B(w_{Dr}^Q)^\dagger B(w_{Ds}^Q)
 \ge-\rho_Qh_Q$$ on the entire Fock space $\mathcal F_Q$.

For the coefficients in Appendix <a href="#app:certificate" data-reference-type="ref" data-reference="app:certificate">8</a>, $$\label{eq:A4bound}
 A_4\le\mathcal L_4(W_4W_4^\dagger)+(1222\varepsilon+o(1))H,
 \qquad Q\to\infty,$$ uniformly on $\mathcal F_Q$.

For sufficiently large $Q$, $$\label{eq:tailbound}
 \mathcal L_3\left(W_3\sum_{z=16}^Qq_z(Q)R_{3,z}W_3^\dagger\right)
 \ge-\delta_QH,$$ where $$\label{eq:delta}
 \delta_Q=\sum_{\substack{17\le z\le Q\\z\text{ odd}}}
       \frac{d_{3,z}}{d_a}|q_z(Q)|(z+1),\qquad
 \delta_Q\longrightarrow\frac{61}{4096}.$$
